# Tests for `parse_duration`

```python
import pytest

from duration import parse_duration  # adjust import to your module name


class TestParseDurationSingleUnit:
    """Single-unit duration strings."""

    def test_seconds_only(self):
        assert parse_duration("45s") == 45

    def test_minutes_only(self):
        assert parse_duration("90m") == 90 * 60  # 5400

    def test_hours_only(self):
        assert parse_duration("1h") == 3600

    def test_single_second(self):
        assert parse_duration("1s") == 1

    def test_zero_value(self):
        assert parse_duration("0h") == 0
        assert parse_duration("0m") == 0
        assert parse_duration("0s") == 0


class TestParseDurationMultipleUnits:
    """Combined duration strings."""

    def test_hours_and_minutes(self):
        assert parse_duration("2h30m") == 2 * 3600 + 30 * 60  # 9000

    def test_hour_minute_second(self):
        assert parse_duration("1h2m3s") == 3600 + 120 + 3  # 3723

    def test_all_units_large(self):
        assert parse_duration("10h59m59s") == 10 * 3600 + 59 * 60 + 59  # 39599

    def test_minutes_and_seconds(self):
        assert parse_duration("30m15s") == 30 * 60 + 15  # 1815


class TestParseDurationEdgeCases:
    """Edge cases and unusual but parseable inputs."""

    def test_empty_string(self):
        assert parse_duration("") == 0

    def test_no_valid_units(self):
        # No digit+unit pairs match
        assert parse_duration("abc") == 0

    def test_number_without_unit(self):
        # "120" has no unit, so nothing matches
        assert parse_duration("120") == 0

    def test_unit_without_number(self):
        # "h" alone has no preceding digit
        assert parse_duration("h") == 0
        assert parse_duration("hms") == 0

    def test_ignores_unknown_units(self):
        # 'd' is not matched by the regex, so it's skipped entirely
        assert parse_duration("5d") == 0

    def test_partial_valid_with_garbage(self):
        # Only the valid digit+unit pairs are extracted
        assert parse_duration("2hxyz30m") == 2 * 3600 + 30 * 60

    def test_leading_and_trailing_garbage(self):
        assert parse_duration("time:1h30m!") == 3600 + 30 * 60

    def test_repeated_same_unit_accumulates(self):
        # Function sums all matches, so repeated units add up
        assert parse_duration("1h1h") == 2 * 3600
        assert parse_duration("30m30m") == 2 * 30 * 60

    def test_out_of_order_units(self):
        # Order doesn't matter; values are summed
        assert parse_duration("30m2h") == 2 * 3600 + 30 * 60

    def test_large_value(self):
        assert parse_duration("1000h") == 1000 * 3600

    def test_multi_digit_numbers(self):
        assert parse_duration("123h456m789s") == 123 * 3600 + 456 * 60 + 789

    def test_leading_zeros(self):
        # int() handles leading zeros fine
        assert parse_duration("01h05m") == 3600 + 5 * 60


class TestParseDurationReturnType:
    def test_returns_int(self):
        result = parse_duration("2h30m")
        assert isinstance(result, int)

    def test_returns_int_for_empty(self):
        assert isinstance(parse_duration(""), int)


@pytest.mark.parametrize(
    "input_str,expected",
    [
        ("45s", 45),
        ("90m", 5400),
        ("1h", 3600),
        ("2h30m", 9000),
        ("1h2m3s", 3723),
        ("", 0),
        ("abc", 0),
        ("5d", 0),
        ("0s", 0),
        ("01h05m", 3900),
    ],
)
def test_parse_duration_parametrized(input_str, expected):
    assert parse_duration(input_str) == expected
```

## Notes on coverage

These tests cover:

- **Single units** — `h`, `m`, `s` individually, including zero and single values.
- **Combined units** — typical multi-unit strings in normal and out-of-order arrangements.
- **Edge cases** that reveal the function's actual (somewhat lenient) behavior:
  - Empty strings, garbage input, numbers without units, units without numbers all return `0`.
  - Unknown units like `d` are silently skipped.
  - Repeated units accumulate (a possible bug, but documented here as current behavior).
- **Return type** verification.
- **Parametrized** sanity checks for quick regression detection.

> **Tip:** A couple of tests (`test_repeated_same_unit_accumulates`, `test_ignores_unknown_units`) document behavior that may be unintended. If the spec intends to *reject* malformed input, the function should raise `ValueError` instead — in which case these tests should be updated to use `pytest.raises(ValueError)`.

